def ran = (ints = $l.select { |x| x.is_a?(Integer) }; "#{$l.size} #{ints == ints.sort}")
def run(label)
  $l = []
  r = yield
  puts "#{label}: #{ran} #{r.inspect}"
rescue ArgumentError, TypeError => e
  puts "#{label}: #{ran} #{e.message}"
end
